1	/* snoglob.msw -- Shared global state for SNOBOL4 interpreter modules
2	 *
3	 * All modules include this to share variable declarations.
4	 * The main module provides the actual storage; library modules
5	 * get duplicate labels that the assembler resolves to the first.
6	 */
7	
8	/* Token types */
9	%DEFINE TK_IDENT 1;
10	%DEFINE TK_INT 2;
11	%DEFINE TK_STR 3;
12	%DEFINE TK_EQ 4;
13	%DEFINE TK_LPAREN 5;
14	%DEFINE TK_RPAREN 6;
