        println!("\nExecuted {} instructions", instructions);
    } else {
        eprintln!("\nExecuted {} instructions", instructions);
    }
    if cli.trace > 0 {
        print!("{}", emu.trace().format_last(cli.trace));
    }
    if cli.dump {
        print_dump(&emu, cli.dump_uart);
