                /* For backward compat: if 1 part, set S_OETY/S_OEV1 */
                IF (EPI = 1) THEN DO;
                    S_OETY(S) = EP_TYP(EPB);
                    S_OEV1(S) = EP_VAL(EPB);
                    IF (S_OETY(S) = OE_STR OR S_OETY(S) = OE_SPAN OR S_OETY(S) = OE_BREAK) THEN
                        S_SPTR(S) = EP_VAL(EPB);
                END;
                ELSE IF (EPI = 2 AND S_OEOP(S) != 0) THEN DO;
                    /* Binary op: part0 OP part1 */
                    S_OETY(S) = OE_BINOP;
                    S_OEV1(S) = EP_VAL(EPB);
                    S_OEV2(S) = EP_VAL(EPB + 1);
                END;
                ELSE IF (EPI >= 2) THEN DO;
                    /* Concatenation */
                    S_OETY(S) = OE_NONE;
                END;
            END;

            IF (TT = TK_COLON) THEN DO;
                CALL LEX;
                IF (TT = TK_IDENT) THEN DO;
                    IF (TB(0) = 83 AND TB(1) = 0) THEN DO;
                        S_GTYP(S) = GT_SUCC;
                        CALL LEX;
                    END;
                    ELSE IF (TB(0) = 70 AND TB(1) = 0) THEN DO;
                        S_GTYP(S) = GT_FAIL;
                        CALL LEX;
                    END;
                END;
                ELSE IF (TT = TK_LPAREN) THEN DO;
                    S_GTYP(S) = GT_UNCOND;
                END;
                IF (TT = TK_LPAREN) THEN DO;
                    CALL LEX;
                    IF (TT = TK_IDENT) THEN DO;
                        /* Detect :(RETURN) and :(FRETURN) */
                        IF (TB(0) = 82 AND TB(1) = 69 AND TB(2) = 84 AND TB(3) = 85 AND TB(4) = 82 AND TB(5) = 78 AND TB(6) = 0) THEN DO;
                            S_GTYP(S) = GT_RET;
                            S_GLBL(S) = 0 - 1;
                            CALL LEX;
                        END;
                        ELSE IF (TB(0) = 70 AND TB(1) = 82 AND TB(2) = 69 AND TB(3) = 84 AND TB(4) = 85 AND TB(5) = 82 AND TB(6) = 78 AND TB(7) = 0) THEN DO;
                            S_GTYP(S) = GT_FRET;
                            S_GLBL(S) = 0 - 1;
                            CALL LEX;
                        END;
                        ELSE DO;
                            S_GLBL(S) = SBSAVE();
                            CALL LEX;
                        END;
                    END;
                    IF (TT = TK_RPAREN) THEN CALL LEX;
                END;
            END;

            DO WHILE (TT != TK_EOL AND TT != TK_EOF);
                CALL LEX;
            END;
            IF (TT = TK_EOL) THEN CALL LEX;
            STCNT = STCNT + 1;
        END;
        ELSE IF (TT = TK_COLON) THEN DO;
            CALL LEX;
            IF (TT = TK_IDENT) THEN DO;
                IF (TB(0) = 83 AND TB(1) = 0) THEN DO;
                    S_GTYP(S) = GT_SUCC;
                    CALL LEX;
                END;
                ELSE IF (TB(0) = 70 AND TB(1) = 0) THEN DO;
                    S_GTYP(S) = GT_FAIL;
                    CALL LEX;
                END;
            END;
            ELSE IF (TT = TK_LPAREN) THEN DO;
                S_GTYP(S) = GT_UNCOND;
            END;
            IF (TT = TK_LPAREN) THEN DO;
                CALL LEX;
                IF (TT = TK_IDENT) THEN DO;
                    IF (TB(0) = 82 AND TB(1) = 69 AND TB(2) = 84 AND TB(3) = 85 AND TB(4) = 82 AND TB(5) = 78 AND TB(6) = 0) THEN DO;
                        S_GTYP(S) = GT_RET;
                        S_GLBL(S) = 0 - 1;
                        CALL LEX;
                    END;
                    ELSE IF (TB(0) = 70 AND TB(1) = 82 AND TB(2) = 69 AND TB(3) = 84 AND TB(4) = 85 AND TB(5) = 82 AND TB(6) = 78 AND TB(7) = 0) THEN DO;
                        S_GTYP(S) = GT_FRET;
                        S_GLBL(S) = 0 - 1;
                        CALL LEX;
                    END;
                    ELSE DO;
                        S_GLBL(S) = SBSAVE();
                        CALL LEX;
                    END;
                END;
                IF (TT = TK_RPAREN) THEN CALL LEX;
            END;
            DO WHILE (TT != TK_EOL AND TT != TK_EOF);
