/* PARSE_BUILTIN_ARG -- parse one full expression in a builtin
 * argument position. Accepts primitives (IDENT/INT/STR), nested
 * calls to SUBSTR/SIZE/CHAR (via PARSE_NESTED_FN), and an
 * optional trailing binary op (+ - *) followed by another primary.
 *
 * Slot layout (postfix): each primary contributes one or more EP
 * slots; an optional binop appears as a marker slot AFTER its
 * second operand. Example for  SIZE(A) - 1 :
 *
 *     [OE_IDENT(A), OE_SIZE, OE_INT(1), OE_OP_SUB]
 *
 * The lowering's postfix walk produces stack actions:
 *   load A   ; OP_SIZE pops A, pushes len   ; load 1   ; OP_SUB.
 *
 * On entry: TT is on the first token of the arg.
 * On exit:  TT is past the arg (typically on a `,` or `)`).
 * Returns the new EPI.
 */
PARSE_BUILTIN_ARG: PROC(EPB INT, START_EPI INT) RETURNS(INT);
    DCL EPI INT;
    DCL NEW_EPI INT;
    DCL OP_TT INT;
    EPI = START_EPI;

    /* First primary: nested call, IDENT, INT, or STR. */
    NEW_EPI = PARSE_NESTED_FN(EPB, EPI);
    IF (NEW_EPI > EPI) THEN EPI = NEW_EPI;
    ELSE IF (TT = TK_IDENT) THEN DO;
        DCL N1 INT;
        N1 = SBSAVE();
        IF (EPI < EPSLOTS) THEN DO;
            EP_TYP(EPB + EPI) = OE_IDENT;
            EP_VAL(EPB + EPI) = SYM_LOOKUP(N1);
            EPI = EPI + 1;
        END;
        CALL LEX;
    END;
    ELSE IF (TT = TK_INT) THEN DO;
        IF (EPI < EPSLOTS) THEN DO;
            EP_TYP(EPB + EPI) = OE_INT;
            EP_VAL(EPB + EPI) = TV;
            EPI = EPI + 1;
        END;
        CALL LEX;
    END;
    ELSE IF (TT = TK_STR) THEN DO;
        IF (EPI < EPSLOTS) THEN DO;
            EP_TYP(EPB + EPI) = OE_STR;
            EP_VAL(EPB + EPI) = SBSAVE();
            EPI = EPI + 1;
        END;
        CALL LEX;
    END;

    /* Optional binary op + second primary. */
    IF (TT = TK_PLUS OR TT = TK_MINUS OR TT = TK_STAR) THEN DO;
        OP_TT = TT;
        CALL LEX;
        NEW_EPI = PARSE_NESTED_FN(EPB, EPI);
        IF (NEW_EPI > EPI) THEN EPI = NEW_EPI;
        ELSE IF (TT = TK_IDENT) THEN DO;
            DCL N2 INT;
            N2 = SBSAVE();
            IF (EPI < EPSLOTS) THEN DO;
                EP_TYP(EPB + EPI) = OE_IDENT;
                EP_VAL(EPB + EPI) = SYM_LOOKUP(N2);
                EPI = EPI + 1;
            END;
            CALL LEX;
        END;
        ELSE IF (TT = TK_INT) THEN DO;
            IF (EPI < EPSLOTS) THEN DO;
                EP_TYP(EPB + EPI) = OE_INT;
                EP_VAL(EPB + EPI) = TV;
                EPI = EPI + 1;
            END;
            CALL LEX;
        END;
        IF (EPI < EPSLOTS) THEN DO;
            IF (OP_TT = TK_PLUS) THEN EP_TYP(EPB + EPI) = OE_OP_ADD;
            ELSE IF (OP_TT = TK_MINUS) THEN EP_TYP(EPB + EPI) = OE_OP_SUB;
            ELSE EP_TYP(EPB + EPI) = OE_OP_MUL;
            EP_VAL(EPB + EPI) = 0;
            EPI = EPI + 1;
        END;
    END;

    RETURN(EPI);
END;

