                CALL AM_EMIT_OP(OP_READ_RAW_INPUT);
            ELSE DO;
                CALL AM_EMIT_OP(OP_LOAD_VAR);
                CALL AM_EMIT_BYTE(EPV);
            END;
        END;
        /* Nested call markers + in-stream binops --
         * each pops its args and pushes its result.
         * Required for builtin args that contain
         * other builtin calls or arithmetic. */
        WHEN (EPT = OE_SIZE)   CALL AM_EMIT_OP(OP_SIZE);
        WHEN (EPT = OE_SUBSTR) CALL AM_EMIT_OP(OP_SUBSTR);
        WHEN (EPT = OE_CHAR)   CALL AM_EMIT_OP(OP_CHAR);
        WHEN (EPT = OE_OP_ADD) CALL AM_EMIT_OP(OP_ADD);
        WHEN (EPT = OE_OP_SUB) CALL AM_EMIT_OP(OP_SUB);
