            lex_init(line, str_len(line));
            while (1) {
                lex_scan();
                tok_print();
                if (cur_type == TOK_EOF) break;
            }
        }
    } else if (len > 0) {
        /* Parse number */
        suite = 0;
        int i = 0;
        while (i < len && line[i] >= 48 && line[i] <= 57) {
            suite = suite * 10 + (line[i] - 48);
            i = i + 1;
        }
        if (!run_suite(suite)) {
            uart_putstr("Unknown suite: ");
            print_int(suite);
            uart_putchar(10);
        }
    }

    return 0;
