                    ELSE DO;
                        CAPSTART = CPOS;
                        CPOS = CPOS + PV;
                    END;
                END;
                WHEN (PT = PK_LIT) DO;
                    DCL LLEN INT;
                    DCL LK INT;
                    DCL LP2 PTR;
                    DCL CP2 PTR;
                    LLEN = SLEN(ADDR(SB) + PV);
                    IF (CPOS + LLEN > SUBJ_LEN2) THEN
                        MATCHED2 = 0;
                    ELSE DO;
                        LK = 0;
                        DO WHILE (LK < LLEN);
                            LP2 = ADDR(SB) + PV + LK;
                            CP2 = ADDR(SB) + SUBJ_OFF2 + CPOS + LK;
                            IF (LP2->DTAG != CP2->DTAG) THEN DO;
                                MATCHED2 = 0;
                                LK = LLEN;
                            END;
                            LK = LK + 1;
                        END;
                        IF (MATCHED2 = 1) THEN
                            CPOS = CPOS + LLEN;
                    END;
                END;
            END;

            PI = PI + 1;
        END;

        IF (MATCHED2 = 0) THEN
            TRYPOS2 = TRYPOS2 + 1;
    END;

    PSTOP = 0;
    LAST_RESULT = MATCHED2;
END;

/* --- Handler: pattern replacement (S pattern = replacement) --- */
EXEC_PAT_REPLACE: PROC;
    DCL RSIDX INT;
    DCL RSUBJ_OFF INT;
    DCL RSUBJ_LEN INT;
    DCL RTRYPOS INT;
    DCL RMATCHED INT;
